WFJ.Data.add("spell", {
  [400009] = { nil, "Stordito.", nil, 0x27f95286, "mu" },
  [400080] = { "Incidi sulla tua armatura per il torso o sulla tua veste la runa Miscela Letale:\n\n$I1\nConferisce diversi miglioramenti ai tuoi veleni:\n\nQuando infliggi un qualsiasi altro veleno a un bersaglio, gli infliggi anche Veleno Mortale.\n\nSe alla tua arma non è applicato alcun veleno, ha una probabilità di attivare Veleno Istantaneo come se Veleno Istantaneo fosse applicato.\n\nVeleno Mortale e Veleno Istantaneo ora traggono più danni dalla tua potenza d'attacco.\n\nIl tuo Veleno Mortale ora può essere attivo sui bersagli colpiti dal Veleno Mortale di un altro Ladro.", nil, 0x1a66a12e, nil, "um" },
  [400081] = { "Incidi sui tuoi gambali la runa In Mezzo agli Occhi:\n\n$I1\nMossa risolutiva a distanza che infligge danni per punto combo, aumentati dalla potenza d'attacco, e stordisce il bersaglio:\n\n$N1 punto: $N2 danni, $D1 di stordimento\n $N4 punti: $N5 danni, $D2 di stordimento\n $N7 punti: $N8 danni, $D3 di stordimento\n $N10 punti: $N11 danni, $D4 di stordimento\n $N13 punti: $N14 danni, $D5 di stordimento\n\nTempo di recupero condiviso con Colpo ai Reni.", nil, 0x7fe6c87f, nil, "um" },
  [400082] = { "Incidi sulla tua armatura per il torso o sulla tua veste la runa Just a Flesh Wound:\n\n$I1\nSubisci il $N1% di danni fisici in meno mentre l'effetto di Lame Danzanti è attivo, ridotti di un ulteriore $N2% ogni $N3 punti di abilità in Difesa oltre $N4. Inoltre, la tua probabilità di schivata viene moltiplicata per il $N5%, la tua probabilità di subire colpi critici dagli attacchi in mischia è ridotta del $N6%, infliggi il $N7% di danni in meno, la minaccia generata da tutte le tue azioni aumenta enormemente e la tua abilità Finta è sostituita da Tease, che provoca il bersaglio inducendolo ad attaccarti.\n\n$I2\nProvoca il bersaglio, inducendolo ad attaccarti, ma non ha effetto se il bersaglio ti sta già attaccando.", nil, 0xd37806b5, nil, "um" },
  [400093] = { "Incidi sui tuoi stivali la runa Rolling with the Punches:\n\n$I1\nOgni volta che schivi o pari, la tua salute aumenta del $N1%, effetto che si accumula fino a $N2 volte.", nil, 0xdc8b0d48, nil, "um" },
  [400094] = { "Incidi sui tuoi guanti la runa Mutilazione:\n\n$I1\nAttacca istantaneamente con entrambe le armi, infliggendo il $N1% dei danni dell'arma più $N2 danni aggiuntivi con ciascuna arma. Danni aumentati del $N3% contro i bersagli avvelenati. Fornisce $N4 punti combo.", nil, 0xb45a10bc, nil, "um" },
  [400095] = { "Incidi sulla tua armatura per il torso o sulla tua veste la runa Estrazione Rapida:\n\n$I1\nEstrai l'arma a distanza e scocchi un tiro rapido contro un nemico, infliggendo i normali danni dell'arma a distanza e riducendo la velocità di movimento del bersaglio del $N1% per $D1. Fornisce $N3 punti combo.\n\nEstrazione Rapida beneficia di tutti i talenti e gli effetti che si attivano da Assalto Funesto o lo modificano.", nil, 0x0baef149, nil, "um" },
  [400096] = { "Incidi sulla tua cintura la runa Lancio dello Shuriken:\n\n$I1\nLancia uno shuriken al nemico, infliggendo danni pari al $N1% della tua potenza d'attacco, e colpisce anche fino a $N2 bersagli aggiuntivi vicini. Fornisce $N3 punti combo per ogni bersaglio colpito.", nil, 0xf3dd9623, nil, "um" },
  [400099] = { "Incidi sui tuoi gambali la runa Lame Danzanti:\n\n$I1\nMossa risolutiva che aumenta la probabilità di parata del $N1% e conferisce $N2 potenza d'attacco per ogni punto di abilità in Difesa oltre $N3. Dura di più per ogni punto combo:\n\n$N4 punto: $N5 s\n $N6 punti: $N7 s\n $N8 punti: $N9 s\n $N10 punti: $N11 s\n $N12 punti: $N13 s", nil, 0xde49cba0, nil, "um" },
  [400101] = { "Incidi sulla tua cintura la runa Passo nell'Ombra:\n\n$I1\nTenta di passare attraverso le ombre per riapparire alle spalle del nemico e aumenta la velocità di movimento del $N1% per $D1.", nil, 0x40b18911, nil, "um" },
  [400104] = { "Incidi sui tuoi gambali la runa Passo nell'Ombra:\n\n$I1\nTenta di passare attraverso le ombre per riapparire alle spalle del nemico e aumenta la velocità di movimento del $N1% per $D1.", nil, 0x70e32775, nil, "um" },
  [400105] = { "Incidi sui tuoi guanti la runa Assalto d'Ombra:\n\n$I1\nTi teletrasporti alle spalle del bersaglio e lo colpisci, infliggendo il $N1% dei danni dell'arma. Utilizzabile solo in Furtività. Fornisce $N2 punti combo.", nil, 0xdfa82ca8, nil, "um" },
  [400589] = { nil, "Riduce del $N1% la durata della canalizzazione del tuo prossimo incantesimo ⟦Arcane Missiles=Missili Arcani⟧, ne riduce il costo in mana del $N2% e fa partire i missili ogni $D1.", nil, 0xf8ba2f76, "mu" },
  [400616] = { "Investe il nemico con $N1 danni da fuoco.", nil, 0x27fcb60f, nil, "um" },
